// ============================================
// SHAMIM WiFi - Panel Update Server (Cloudflare Worker)
// Serves both files needed by the SHAMIM WiFi hotspot system:
//   /shamim  -> admin panel CGI script  (install to /www/cgi-bin/shamim)
//   /theme   -> openNDS voucher theme   (install to /usr/lib/opennds/theme_voucher.sh)
// Panel size: 68979 bytes
// Theme size: 26691 bytes
// URL:  https://wifipanel1.shamim-iptv.workers.dev/
// ============================================

const FILE_B64 = "";

const THEME_B64 = "";

function b64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === "/shamim") {
      const bytes = b64ToBytes(FILE_B64);
      return new Response(bytes, {
        headers: {
          "Content-Type": "application/octet-stream",
          "Content-Disposition": "attachment; filename=shamim",
          "Content-Length": String(bytes.length),
          "Cache-Control": "no-store",
        },
      });
    }

    if (url.pathname === "/theme") {
      const bytes = b64ToBytes(THEME_B64);
      return new Response(bytes, {
        headers: {
          "Content-Type": "application/octet-stream",
          "Content-Disposition": "attachment; filename=theme_voucher.sh",
          "Content-Length": String(bytes.length),
          "Cache-Control": "no-store",
        },
      });
    }

    return new Response(
      "SHAMIM WiFi Panel Server - OK\nDownload panel: /shamim\nDownload theme:  /theme",
      { headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" } }
    );
  },
};
